// Authored practice questions grounded in the eight lessons; not actual exam questions.
// The keyed option is authored separately, then choices are shuffled with a stable stem hash.
const bankQuestion=(topic,difficulty,stem,correct,distractors,why)=>{
 let seed=2166136261;for(const c of stem)seed=Math.imul(seed^c.charCodeAt(0),16777619)>>>0;
 const options=[{text:correct,key:true},...distractors.map(text=>({text,key:false}))];
 for(let i=options.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[options[i],options[j]]=[options[j],options[i]];}
 return {topic,difficulty,stem,choices:options.map(x=>x.text),answer:options.findIndex(x=>x.key),why};
};
